AS
BEGIN
    SET NOCOUNT ON;
    DECLARE @companyId INT;
    DECLARE @startDate DATE;
    DECLARE @endDate DATE;
    DECLARE @sourceId NVARCHAR(64);
    DECLARE @onlyNewLeads BIT;

    -- Hermosillo is fixed UTC-7 with no DST. Convert local dates to UTC DATETIME bounds.
    DECLARE @startDateTime2 DATETIME;
    DECLARE @endDateTime2 DATETIME;

    SELECT TOP 1
        @companyId      = TRY_CONVERT(INT, JSON_VALUE(value, '$.companyId')),
        @startDate      = TRY_CONVERT(DATE, JSON_VALUE(value, '$.startDate')),
        @endDate        = TRY_CONVERT(DATE, JSON_VALUE(value, '$.endDate')),
        @sourceId       = JSON_VALUE(value, '$.sourceId'),
        @onlyNewLeads   = TRY_CONVERT(BIT, JSON_VALUE(value, '$.onlyNewLeads'))
    FROM OPENJSON(@pjsonfile, '$.marketingLeadAttributions');

    -- Default startDate to 30 days ago if not provided
    IF @startDate IS NULL
        SET @startDate = DATEADD(day, -30, CAST(DATEADD(HOUR, -7, SYSUTCDATETIME()) AS DATE));

    -- Default endDate to today if not provided
    IF @endDate IS NULL
        SET @endDate = CAST(DATEADD(HOUR, -7, SYSUTCDATETIME()) AS DATE);

    -- Convert Hermosillo dates to UTC DATETIME range for filtering
    SET @startDateTime2 = DATEADD(HOUR, 7, CAST(@startDate AS DATETIME)); -- Start of Hermosillo day to UTC
    SET @endDateTime2   = DATEADD(SECOND, -1, DATEADD(DAY, 1, DATEADD(HOUR, 7, CAST(@endDate AS DATETIME)))); -- End of Hermosillo day (23:59:59) to UTC

    SELECT TOP 200 -- Max 200 rows as per PRD hint
        marketingLeadAttributionId,
        ISNULL(companyId, 0) AS companyId,
        ISNULL(provider, '') AS provider,
        ISNULL(conversionChannel, '') AS conversionChannel,
        ISNULL(channelId, 0) AS channelId,
        ISNULL(customerPhone, '') AS customerPhone,
        ISNULL(clientId, 0) AS clientId,
        ISNULL(isNewLead, 0) AS isNewLead,
        ( -- Compute touchNumber across all records for the company and customer phone
            SELECT rn FROM (
                SELECT
                    mla_inner.marketingLeadAttributionId,
                    ROW_NUMBER() OVER (PARTITION BY mla_inner.companyId, mla_inner.customerPhone ORDER BY mla_inner.referredAt) AS rn
                FROM dbo.marketingLeadAttributions AS mla_inner
                WHERE mla_inner.companyId = T.companyId AND mla_inner.customerPhone = T.customerPhone
            ) AS touchNumbers WHERE touchNumbers.marketingLeadAttributionId = T.marketingLeadAttributionId
        ) AS touchNumber,
        ISNULL(sourceType, '') AS sourceType,
        ISNULL(sourceId, '') AS sourceId,
        ISNULL(headline, '') AS headline,
        ISNULL(sourceUrl, '') AS sourceUrl,
        ISNULL(mediaType, '') AS mediaType,
        referredAt
    FROM dbo.marketingLeadAttributions AS T
    WHERE companyId = @companyId
      AND (@sourceId IS NULL OR sourceId = @sourceId)
      AND (@onlyNewLeads IS NULL OR @onlyNewLeads = 0 OR isNewLead = 1)
      AND referredAt >= @startDateTime2
      AND referredAt <= @endDateTime2
    ORDER BY referredAt DESC
    FOR JSON AUTO, ROOT('marketingLeadAttributions');
END;
