def record_referral(payload: dict):
    """
    Records a marketing lead attribution from a WhatsApp referral.
    This function is called internally, not exposed as a public API route.
    It performs an idempotent insert via sp_marketingLeadAttributions.
    Returns a dictionary indicating status and result or error.
    """
    conn = cursor = None
    with workflow_step("record_marketing_lead_attribution", workflow_name="marketing_attribution") as step:
        try:
            conn = connection()
            cursor = conn.cursor()
            # The SP expects a key like "marketingLeadAttributions" wrapping the payload
            sp_payload = {"marketingLeadAttributions": [payload]}
            cursor.execute("EXEC [dbo].[sp_marketingLeadAttributions] @pjsonfile = %s", (json.dumps(sp_payload),))

            row = cursor.fetchone() # Upsert SP returns ONE row, ONE column
            raw_result = row[0] if row and row[0] else '{"message": "ok"}'

            result_dict = json.loads(raw_result)

            if "error" in result_dict:
                step.status = "FAILED"
                step.details = {"sp_error": result_dict["error"]}
                log_workflow_step(workflow_name="marketing_attribution", status="FAILED", details={
