                    "companyId": payload.get("companyId"),
                    "externalEventId": payload.get("externalEventId")
                }, correlation_id=step.correlation_id, workflow_id=step.workflow_id)
                return {"status": "error", "message": result_dict["error"]}

            log_workflow_step(workflow_name="marketing_attribution", status="COMPLETED", correlation_id=step.correlation_id, workflow_id=step.workflow_id)
            return {"status": "success", "result": result_dict}
