      "marketingLeadAttributions": [
        { "marketingLeadAttributionId": marketingLeadAttributionId, "companyId": companyId }
      ]
    }),
  });
  if (!res.ok) {
    throw new Error(await res.text());
  }
  const data: MarketingLeadAttributionOneResponse = await res.json();
  return data.marketingLeadAttributions?.[0] ?? null;
}
