    "content": "import { useCallback, useEffect, useState } from 'react';
import { useIonViewWillEnter } from '@ionic/react';
import { useUser } from '../../../contexts/UserContext';
import { useToast } from '../../../hooks/useToast';
import { onDataChanged } from '../../../utils/refreshBus';
import {
  getAllMarketingLeadAttributions,
  getOneMarketingLeadAttribution,
  MarketingLeadAttributionForList,
  MarketingLeadAttributionForDetail,
  MarketingLeadAttributionFilters
} from '../../../api/marketingLeadAttributionApi';

export const useMarketingLeadAttribution = () => {
  const { companyId } = useUser();
  const { showToast, toastProps } = useToast();
  const [items, setItems] = useState<MarketingLeadAttributionForList[]>([]);
  const [loading, setLoading] = useState(false);
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedItemId, setSelectedItemId] = useState<number | null>(null);
  const [selectedItem, setSelectedItem] = useState<MarketingLeadAttributionForDetail | null>(null);
  const [detailLoading, setDetailLoading] = useState(false);

  // Default filters for the list view
  const [filters, setFilters] = useState<MarketingLeadAttributionFilters>({
    companyId: companyId,
    endDate: new Date().toISOString().slice(0, 10), // Today
    startDate: new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10), // Last 30 days
    // sourceId: undefined,
    // onlyNewLeads: undefined
  });

  const loadAttributions = useCallback(async () => {
    setLoading(true);
    try {
      const fetchedItems = await getAllMarketingLeadAttributions({ ...filters, companyId });
      setItems(fetchedItems);
    } catch (err) {
      showToast((err as Error).message, 'danger');
    } finally {
      setLoading(false);
    }
  }, [companyId, filters, showToast]);

  const loadDetailItem = useCallback(async (id: number) => {
    setDetailLoading(true);
    try {
      const item = await getOneMarketingLeadAttribution(id, companyId);
      setSelectedItem(item);
    } catch (err) {
      showToast((err as Error).message, 'danger');
    } finally {
      setDetailLoading(false);
    }
  }, [companyId, showToast]);

  useEffect(() => {
    if (companyId) {
      loadAttributions();
    }
  }, [loadAttributions, companyId]);

  useIonViewWillEnter(() => {
    if (companyId) {
      loadAttributions();
    }
  });

  useEffect(() => onDataChanged(() => loadAttributions()), [loadAttributions]);

  const openDetailModal = async (id: number) => {
    setSelectedItemId(id);
    await loadDetailItem(id);
    setShowDetailModal(true);
  };

  const closeDetailModal = () => {
    setShowDetailModal(false);
    setSelectedItemId(null);
    setSelectedItem(null);
  };

  const handleFilterChange = (newFilters: Partial<MarketingLeadAttributionFilters>) => {
    setFilters(prev => ({ ...prev, ...newFilters }));
  };

  return {
    items,
    loading: loading || detailLoading,
    toastProps,
    filters,
    handleFilterChange,
    showDetailModal,
    openDetailModal,
    closeDetailModal,
    selectedItem
  };
};

export type MarketingLeadAttributionVM = ReturnType<typeof useMarketingLeadAttribution>;
